import { defaultClientConditions, defaultServerConditions, type Plugin } from "vite-plus";

// Workspace packages export their TypeScript under the `source` condition (generated by `vp pack`,
// `exports.devExports`), so dev, tests and type checks never need another package built first.
// Add this plugin to every vite.config.ts that imports a workspace package; tsconfig needs
// `"customConditions": ["source"]` too (RFC 0002). A package doing so must build declarations from a
// src-only tsconfig (`pack.dts.tsconfig`), or tsgo also emits this file's .d.ts at the root.
export function workspaceSource(): Plugin {
  return {
    name: "brigade:workspace-source",
    // After framework plugins (the Cloudflare one sets its own conditions), for every environment.
    enforce: "post",
    configEnvironment(name, config) {
      const client = (config.consumer ?? (name === "client" ? "client" : "server")) === "client";
      const conditions =
        config.resolve?.conditions ?? (client ? defaultClientConditions : defaultServerConditions);
      if (conditions.includes("source")) return;
      config.resolve = { ...config.resolve, conditions: ["source", ...conditions] };
    },
  };
}
